async function campaign4460(birthdays){const org=current?.id,g=generation,root=$('crmCampaignRows4460');if(!org||!unitAllowed21)return;root.textContent='Consultando…';const [cs,rs,bs]=await Promise.all(['customers','relationships','bookingRequests'].map(k=>getDocs(collection(db,'establishments',org,k))));if(g!==generation||current?.id!==org)return;const people=new Map(),last=new Map(),future=new Set(),today=dateKey(new Date());for(const d of cs.docs){const x=d.data();people.set(relationshipKey4460(x),x);}for(const d of bs.docs){const x=d.data(),k=relationshipKey4460(x);if(!k)continue;if(!people.has(k))people.set(k,x);if(x.status==='completed'&&x.date<=today&&(!last.has(k)||last.get(k)<x.date))last.set(k,x.date);if(['pending','confirmed'].includes(x.status)&&x.date>=today)future.add(k);}root.replaceChildren();for(const d of rs.docs){const v=d.data(),x=people.get(d.id),day=last.get(d.id);if(!x||!v.consent)continue;if(birthdays?(!v.birth||v.birth.slice(5,7)!==today.slice(5,7)):(!day||days4450(day)<Number($('crmDays4460').value)||future.has(d.id)))continue;const a=document.createElement('article');a.append(node395('strong',x.name||'Cliente'),node395('p',birthdays?'Aniversário: '+v.birth.slice(8,10)+'/'+v.birth.slice(5,7):days4450(day)+' dias sem atendimento'));const phone=String(x.phone||'').replace(/\D/g,'');if(phone.length>=10&&phone.length<=15){const link=document.createElement('a');link.textContent='Abrir WhatsApp';link.target='_blank';link.rel='noopener noreferrer';const number=phone.length<=11?'55'+phone:phone;const msg=birthdays?`Olá, ${x.name}! Feliz aniversário! Um abraço da ${current.name}.`:`Olá, ${x.name}! Que tal alinhar o visual na ${current.name}? Temos horários disponíveis.`;link.href='https://wa.me/'+number+'?text='+encodeURIComponent(msg);a.append(link);}root.append(a);}if(!root.children.length)root.textContent='Nenhum cliente autorizado neste filtro.';}
$('crmCampaign4460').onclick=()=>run(()=>campaign4460(false));$('crmBirth4460').onclick=()=>run(()=>campaign4460(true));
$('couponForm4460').onsubmit=e=>{e.preventDefault();run(async()=>{const org=current?.id,g=generation;if(!org||!unitAllowed21)return;const code=$('couponCode4460').value.trim().toUpperCase(),offer=$('couponOffer4460').value.trim(),until=$('couponUntil4460').value;if(!/^[A-Z0-9_-]{3,24}$/.test(code)||!offer||until<dateKey(new Date()))throw Error('Confira código, oferta e validade.');await setDoc(doc(db,'establishments',org,'coupons',code),{offer,until});if(g!==generation||current?.id!==org)return;$('couponForm4460').reset();await coupons4460();});};
async function coupons4460(){const org=current?.id,g=generation,root=$('couponRows4460');if(!org||!unitAllowed21)return;const snap=await getDocs(collection(db,'establishments',org,'coupons'));if(g!==generation||current?.id!==org)return;root.replaceChildren();for(const d of snap.docs){const v=d.data(),a=document.createElement('article'),b=node395('button','Excluir cupom');b.type='button';b.className='secondary';a.append(node395('strong',d.id),node395('p',v.offer+' · até '+waDate(v.until)),b);b.onclick=()=>run(async()=>{if(g!==generation||current?.id!==org||!confirm('Excluir este cupom?'))return;await deleteDoc(d.ref);await coupons4460();});root.append(a);}if(!root.children.length)root.textContent='Nenhum cupom cadastrado.';}
$('couponLoad4460').onclick=()=>run(coupons4460);
async function loadOffers4460(u,g){const root=$('offers4460');root.replaceChildren();try{const snap=await getDocs(collection(db,'establishments',bookingOrg,'coupons'));if(g!==generation||auth.currentUser?.uid!==u.uid)return;for(const d of snap.docs){const v=d.data();if(v.until<dateKey(new Date()))continue;const a=document.createElement('article');a.append(node395('strong','Cupom '+d.id),node395('p',v.offer+' · válido até '+waDate(v.until)),node395('p','Apresente no atendimento.'));root.append(a);}}catch(e){console.warn('Cupons indisponíveis',e.code);}}
$('shareFriend4460').onclick=()=>run(async()=>{if(!bookingOrg||!catalog)return;const url=new URL('./index.html',location.href);url.searchParams.set('agenda',bookingOrg);const text='Conheça '+catalog.name+' e agende seu horário!';if(navigator.share){try{await navigator.share({title:catalog.name,text,url:url.href});}catch(e){if(e.name!=='AbortError')throw e;}}else window.open('https://wa.me/?text='+encodeURIComponent(text+' '+url.href),'_blank','noopener,noreferrer');});
function renderCompare4460(){const root=$('monthCompare4460');root.replaceChildren();if(!current||!unitAllowed21)return;const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),1),prev=new Date(now.getFullYear(),now.getMonth()-1,1),end=new Date(now.getFullYear(),now.getMonth(),0),prevEnd=new Date(prev.getFullYear(),prev.getMonth(),Math.min(now.getDate(),end.getDate()));const filter=(a,b)=>financeRows.filter(x=>x.date>=dateKey(a)&&x.date<=dateKey(b)),a=filter(start,now),b=filter(prev,prevEnd);for(const [label,fn] of [['Agendamentos',r=>r.length],['Concluídos',r=>r.filter(x=>x.status==='completed').length],['Cancelados',r=>r.filter(x=>x.status==='cancelled').length]]){const n=fn(a),old=fn(b),box=document.createElement('article');box.append(node395('h3',label),node395('p',`Atual: ${n} · Anterior: ${old}`),node395('p',old?`${Math.round((n-old)/old*100)}% de variação`:'Sem base anterior para comparação'));root.append(box);}}

// 44.64 — metas cumulativas, recompensas imutáveis e resgate pelo gestor.
const rewardKind64={product:'Produto',coupon:'Cupom',service:'Serviço'};
function rewardCollection64(org,k){return collection(db,'establishments',org,k);}
async function loadMilestones64(){const org=current?.id,g=generation;if(!org||!unitAllowed21)return;const [items,goals]=await Promise.all([getDocs(rewardCollection64(org,'rewardItems')),getDocs(rewardCollection64(org,'milestones'))]);if(g!==generation||current?.id!==org)return;const list=items.docs.map(d=>({id:d.id,...d.data()}));$('rewardItems64').replaceChildren(...list.map(x=>node395('p',rewardKind64[x.type]+' · '+x.name)));const choices=[...services.filter(x=>x.active).map(x=>({id:'service:'+x.id,name:x.name,type:'service'})),...list.map(x=>({...x,id:'item:'+x.id}))];$('milestoneItem64').replaceChildren(option('','Selecione uma recompensa'),...choices.map(x=>option(x.id,rewardKind64[x.type]+' · '+x.name)));$('milestones64').replaceChildren(...goals.docs.map(d=>d.data()).sort((a,b)=>a.goal-b.goal).map(x=>node395('p',x.goal+' atendimentos · '+rewardKind64[x.type]+' · '+x.name)));}
$('rewardItemForm64').onsubmit=e=>{e.preventDefault();run(async()=>{const org=current?.id,g=generation;if(!org||!unitAllowed21)return;const name=$('rewardItemName64').value.trim(),type=$('rewardType64').value;if(!name)throw Error('Informe a recompensa.');await setDoc(doc(rewardCollection64(org,'rewardItems')),{name,type});if(g!==generation)return;e.target.reset();await loadMilestones64();});};
$('milestoneForm64').onsubmit=e=>{e.preventDefault();run(async()=>{const org=current?.id,g=generation,goal=Number($('milestoneGoal64').value),[kind,id]=$('milestoneItem64').value.split(':');if(!org||!id||!Number.isInteger(goal)||goal<1||goal>10000)throw Error('Confira a meta.');const source=await getDoc(doc(db,'establishments',org,kind==='service'?'services':'rewardItems',id));if(g!==generation||current?.id!==org)return;if(!source.exists())throw Error('Recompensa indisponível.');const x=source.data(),type=kind==='service'?'service':x.type;if(!confirm('Publicar meta permanente de '+goal+' atendimentos?'))return;await setDoc(doc(db,'establishments',org,'milestones',String(goal)),{goal,type,name:x.name,itemId:id});if(g!==generation)return;e.target.reset();await loadMilestones64();});};
async function wallet64(count){const uid=auth.currentUser?.uid,org=bookingOrg,g=generation;if(!uid||!org)return;const [goals,red]=await Promise.all([getDocs(rewardCollection64(org,'milestones')),getDocs(query(rewardCollection64(org,'milestoneRedemptions'),where('uid','==',uid)))]);if(g!==generation||auth.currentUser?.uid!==uid)return;const used=new Set(red.docs.map(d=>d.data().goal)),root=$('wallet64');root.replaceChildren();const rows=goals.docs.map(d=>d.data()).sort((a,b)=>a.goal-b.goal);if(!rows.length)return;root.append(node395('h3','Sua jornada de recompensas'));for(const x of rows){const a=node395('article');a.append(node395('strong',x.goal+' atendimentos · '+x.name),node395('p',used.has(x.goal)?'Resgatado':count>=x.goal?'Conquistado — apresente no atendimento':'Faltam '+(x.goal-count)+' atendimentos'));root.append(a);}}
function addRedemptions64(a,uid,visits,org,g){const b=node395('button','Recompensas acumuladas');b.type='button';b.className='secondary';const root=node395('div');a.append(b,root);b.onclick=()=>run(async()=>{const [goals,red]=await Promise.all([getDocs(rewardCollection64(org,'milestones')),getDocs(query(rewardCollection64(org,'milestoneRedemptions'),where('uid','==',uid)))]);if(g!==generation||current?.id!==org)return;root.replaceChildren();const used=new Set(red.docs.map(d=>d.data().goal));for(const x of goals.docs.map(d=>d.data()).sort((a,b)=>a.goal-b.goal)){const row=node395('p',x.name+' · '+x.goal+' atendimentos · '+(used.has(x.goal)?'Resgatado':visits.length>=x.goal?'Disponível':'Em progresso'));root.append(row);if(!used.has(x.goal)&&visits.length>=x.goal){const redeem=node395('button','Confirmar resgate');redeem.type='button';root.append(redeem);redeem.onclick=()=>run(async()=>{if(g!==generation||current?.id!==org||!confirm('Confirmar entrega de '+x.name+'?'))return;const fresh=await getDocsFromServer(query(rewardCollection64(org,'bookingRequests'),where('uid','==',uid)));if(g!==generation||current?.id!==org)return;if(fresh.docs.filter(d=>d.data().status==='completed').length<x.goal)throw Error('Meta ainda não atingida.');const ref=doc(db,'establishments',org,'milestoneRedemptions',uid+'_'+x.goal);await runTransaction(db,async tx=>{if((await tx.get(ref)).exists())throw Error('Recompensa já resgatada.');tx.set(ref,{uid,goal:x.goal,redeemedAt:serverTimestamp()});});await renderCustomers();});}}if(!root.children.length)root.textContent='Nenhuma meta publicada.';});}
